eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"effarigQuotes\": () => (/* binding */ effarigQuotes)\n/* harmony export */ });\nconst effarigQuotes = {\n  initial: {\n    id: 0,\n    lines: [{\n      text: \"Welcome to my humble abode! <br> I am Effarig, and I govern Glyphs.\" //image: \"effarig_greet.png\"\n\n    }, {\n      text: `I am different from Orias; not as simplistic as you think. \\\n        <br> I use the shards of Glyphs to enforce my will. <br> I collect them for the bounty of this realm.` //image: \"effarig_relics.png\"\n\n    }, {\n      text: \"What are you waiting for? Get started.\" //image: \"effarig_greet.png\"\n\n    }]\n  },\n  unlockWeights: {\n    id: 1,\n    lines: [{\n      text: \"Do you like my little shop? It is not much, but it is mine.\" //image: \"effarig_shop.png\"\n\n    }]\n  },\n  unlockGlyphFilter: {\n    id: 2,\n    lines: [{\n      text: \"This purchase will help you out.\" //image: \"effarig_shop.png\"\n\n    }]\n  },\n  unlockSetSaves: {\n    id: 3,\n    lines: [{\n      text: \"Is that too much? I think it is too much.\" //image: \"effarig_shop.png\"\n\n    }]\n  },\n  unlockRun: {\n    id: 4,\n    lines: [{\n      text: \"You bought out my entire stock... well, at least I am rich now.\" //image: \"effarig_sold.png\"\n\n    }, {\n      text: `The heart of my Reality is suffering. Each Layer is harder \n        than the last... <br> I hope you never complete it.` //image: \"effarig_heart.png\"\n\n    }]\n  },\n  completeInfinity: {\n    id: 5,\n    lines: [{\n      text: \"You have completed Effarig's Infinity.\",\n      showCelestialName: false //image: \"effarig_infinity.png\"\n\n    }, {\n      text: `This is the first threshold. It only gets worse from here. \n        None but me know enough about my domain to get further.` //image: \"effarig_mad.png\"\n\n    }]\n  },\n  completeEternity: {\n    id: 6,\n    lines: [{\n      text: \"You have completed Effarig's Eternity.\",\n      showCelestialName: false //image: \"effarig_eternity.png\"\n\n    }, {\n      text: `This is the limit. I do not want you to proceed past this point. \n        You will not finish this in your lifetime. I will just wait here until you give up.` //image: \"effarig_mad.png\"\n\n    }]\n  },\n  completeReality: {\n    id: 7,\n    lines: [{\n      text: \"You have completed Effarig's Reality.\",\n      showCelestialName: false //image: \"effarig_reality.png\"\n\n    }, {\n      text: `So this is the diabolical power... what frightened the others...` //image: \"effarig_fear.png\"\n\n    }, {\n      text: `Do you think this was worth it? Trampling on what I have done? \n        And for what purpose? You could have joined, we could have cooperated.` //image: \"effarig_sad.png\"\n\n    }, {\n      text: `But no. It is over. <br> Leave while I cling onto what is left.` //image: \"effarig_over.png\"\n\n    }]\n  }\n};//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///./src/core/secret-formula/celestials/quotes/effarig.js\n");

